INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('023daefa-b586-426f-b63e-2b57be380042', 'verb, third person, sing.', 'warns of; phrasal verb', 'DE', 'EN-GB', 'Der Gemeinde *warnt vor* Hochwasser.', 'The community warns of floods.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('560ff51c-0b1f-47a3-bcc3-ff31d6d778fe', 'verb, first person, plural; phrasal verb', 'to look forward to', 'DE', 'EN-GB', 'Wir *freuen uns auf* die Party.', 'We look forward to the party.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('5ba101d4-0b9e-4b05-b786-3e3a8f66c2ae', 'verb, base form', 'subsidize', 'DE', 'EN-GB', 'Die Regierung hat beschlossen, den Preis für U-Bahn-Tickets zu *subventionieren*.', 'The government has decided to subsidize the price of subway passes.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('932f47dc-bc50-4f99-9e89-3fa29647a299', 'adjecive, masculine, sing.', 'infallible', 'DE', 'EN-GB', 'Mücken haben einen *untrüglichen* Geruchssinn, um herauszufinden, wen sie stechen wollen.', 'Mosquitoes have an infallible sense of smell to find who to bite.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('cbfa4479-651d-4a02-ac98-803459beee87', 'adjective, base form', 'independent', 'DE', 'EN-GB', 'Junge Spanier werden fast im Alter von 30 Jahren *unabhängig*.', 'Young Spaniards become independent almost at the age of 30.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('6a96dc69-97c4-4c02-b266-e5a8c4a49350', 'noun, neuter dative plural', 'heart', 'DE', 'EN-GB', 'Aus Hafer, von *Herzen*.', 'Made from oats, from the heart.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('eb5e3485-d751-446c-a5df-8ef7b9bb147e', 'noun, masculine sing. nominative', 'regular', 'DE', 'EN-GB', 'Er ist ein *regelmäßiger* Gast.', 'He is a regular guest.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('23910d1e-e073-41ca-b481-cbe3257f7ad1', 'noun, femenine sing. nominative', 'monthly', 'DE', 'EN-GB', 'Die *monatliche* Rechnungsstellung erfolgt 60 Tage nach Ende der Abgabeperiode.', 'The monthly invoice is issued 60 days after the end of the delivery period.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('b0d33c13-f471-4dc0-8290-b1db0c83b4c8', 'noun, sing. masculine, n-Deklination', 'mister, sir', 'DE', 'EN-GB', 'Herr Elkart zeigt *Herrn* Hellmann den gesäuberten Teppich.', 'Mr. Elkart shows Mr. Hellmann the cleaned carpet.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('e1b635fc-2c16-49a3-a0d2-be1093936e11', 'noun, sing. masculine, n-Deklination', 'colleague', 'DE', 'EN-GB', 'Nina fragt ihren *Kollegen*, ob sie alles richtig macht.', 'Nina asks her colleague if she is doing everything right.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('29ca1eb1-4b6a-4e7b-bcc2-5be65cba17d0', 'noun, sing. masculine, n-Deklination', 'specialist', 'DE', 'EN-GB', 'Die Firma sucht einen *Spezialisten* für Gebäudereinigung.', 'The company is looking for a specialist in building cleaning.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('b118c570-121c-46f2-8e58-9e0a1f1e70d4', 'noun, plural femenine', 'tears of joy', 'DE', 'EN-GB', 'Die Menschen laufen mit *Freudentränen* durch die Stadt.', 'People run through the city with tears of joy.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('57afe77a-1b35-4b22-abcc-c759cf64e7e6', 'noun, sing. femenine', 'World Cup', 'DE', 'EN-GB', 'In wenigen Tagen beginnt die *Weltmeisterschaft* in Katar.', 'In a few days, the World Cup will begin in Qatar.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('018cae1f-ee64-4654-9358-11a3a50b646e', 'adjective, sing. neuter', 'artistic', 'DE', 'EN-GB', 'Ab dem Wochenende gibt es ein buntes *künstlerisches* Programm in der Staadt.', 'From the weekend there will be a colorful artistic program in the city.');
