INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('d206929e-d73b-465a-af51-4ff8d26b2380', 'preposition + noun', 'Starting from this weekend', 'DE', 'EN-GB', '*Ab dem Wochenende* gibt es ein buntes künstlerisches Programm in der Staadt.', 'Starting from this weekend there will be a colorful artistic program in the city.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('b61a41e0-449e-4973-9263-98f5c9ef5897', 'noun, masculine, sing.', 'sense of smell', 'DE', 'EN-GB', 'Mücken haben einen untrüglichen *Geruchssinn*, um herauszufinden, wen sie stechen wollen.', 'Mosquitoes have an infallible sense of smell to find who to bite.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('171f48fa-9a83-48dd-9c82-7c412d3e52c2', 'adjective; base form', 'embarrassing', 'DE', 'EN-GB', 'Ein anderer Nutzer kann über die ganze Diskussion nur den Kopf schütteln: „Schon *peinlich*, über was sich hier alles beschwert wird.“', 'Another user can only shake his head at the whole discussion: "It''s awkward what people complain about here."');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('5ec9622f-5ced-4121-bd71-9d73be38cb35', '3rd pers. sing.; simpe past', 'read', 'DE', 'EN-GB', 'Sie *las* den Kindern ein Buch vor.', 'She read a book to the children.');
