INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('e1be73ea-5647-4990-bbd4-1c15c0182ba6', '3rd pers. sing.; simple past', 'didn''t get', 'DE', 'EN-GB', 'Er *bekam* keine Hilfe.', 'He didn''t get any help.');
