INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('d46d73fd-46b4-46c9-a7a3-51ddd2653d78', '3rd pers. sing.; simple past', 'did, took care of', 'DE', 'EN-GB', 'Benjamin *erledigte* seine Aufgaben.', 'Benjamin did his chores.');
