INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('4c10a041-69b7-4a18-b118-0744f97d331e', '3rd pers. sing.; simple past', '(liked to) sing, sang', 'DE', 'EN-GB', 'Paula *sang* gerne Lieder.', 'Paula liked to sing songs.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('321b5832-5331-4b96-97db-5a17c1995088', '1st pers. sing.; simple past', 'thought of', 'DE', 'EN-GB', 'Ich *dachte an* dich.', 'I thought of you.');
