INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('87267bf5-01a9-453c-b9ce-974d0d505ebc', '1st pers. sing.; simple past', '(did not) find', 'DE', 'EN-GB', 'Ich *fand* den Ausgang nicht.', 'I did not find the exit.');
INSERT INTO `cards` (`card_id`, `grammar`, `hint`, `lang_learn`, `lang_user`, `prompt`, `translation`) VALUES ('0b492af5-2a3d-40e6-9c75-c8955a7746d2', '1st pers. plural; simple past', 'went', 'DE', 'EN-GB', 'Wir *gingen* nach Hause.', 'We went home.');
